-- A109 — torres e blocos internos em rascunho, sem unidades, pavimentos, metragem, endereço, estoque, disponibilidade, preço, proposta, contrato ou financeiro.
create type public.urban_development_structure_kind as enum ('tower', 'block');
create table public.urban_development_structures (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, development_id uuid not null, internal_reference text not null check (internal_reference ~ '^[A-Z][A-Z0-9_]{2,79}$'), structure_kind public.urban_development_structure_kind not null, state public.party_lifecycle_state not null default 'draft', created_by uuid not null references public.identity_subjects(user_id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint urban_development_structures_development_fk foreign key (development_id, organization_id) references public.urban_developments(id, organization_id) on delete restrict, constraint urban_development_structures_reference_unique unique (organization_id, development_id, internal_reference), constraint urban_development_structures_tenant_match unique (id, organization_id));
create index urban_development_structures_context_lookup on public.urban_development_structures (organization_id, development_id, state, created_at desc);
alter table public.urban_development_structures enable row level security; revoke all on table public.urban_development_structures from public, anon, authenticated; create policy urban_development_structures_deny_direct_access on public.urban_development_structures as restrictive for all to public using (false) with check (false);
create or replace function public.urban_create_draft_development_structure(p_actor_user_id uuid, p_organization_id uuid, p_module public.operating_module, p_purpose_code text, p_development_id uuid, p_internal_reference text, p_structure_kind public.urban_development_structure_kind, p_correlation_id uuid) returns uuid language plpgsql security definer set search_path = '' as $$ declare v_existing_target uuid; v_structure_id uuid; begin perform private.require_urban_pipeline_authority(p_actor_user_id, p_organization_id, p_module, p_purpose_code); select target_id into v_existing_target from public.admin_audit_events where command_name = 'urban_create_draft_development_structure' and correlation_id = p_correlation_id and outcome = 'allowed' order by occurred_at desc limit 1; if v_existing_target is not null then return v_existing_target; end if; if not exists (select 1 from public.urban_developments where id = p_development_id and organization_id = p_organization_id and state = 'draft') then raise exception using errcode = '42501', message = 'URBAN_DEVELOPMENT_STRUCTURE_CONTEXT_DENIED'; end if; insert into public.urban_development_structures (organization_id, development_id, internal_reference, structure_kind, state, created_by) values (p_organization_id, p_development_id, trim(upper(p_internal_reference)), p_structure_kind, 'draft', p_actor_user_id) returning id into v_structure_id; insert into public.admin_audit_events (correlation_id, actor_user_id, organization_id, command_name, outcome, target_type, target_id, payload_redacted) values (p_correlation_id, p_actor_user_id, p_organization_id, 'urban_create_draft_development_structure', 'allowed', 'urban_development_structure', v_structure_id, jsonb_build_object('module', p_module::text, 'purpose_code', trim(p_purpose_code), 'structure_kind', p_structure_kind::text)); return v_structure_id; end; $$;
create or replace function public.urban_list_draft_development_structures(p_actor_user_id uuid, p_organization_id uuid, p_module public.operating_module, p_purpose_code text) returns table (structure_id uuid, development_id uuid, development_reference text, internal_reference text, structure_kind public.urban_development_structure_kind, created_at timestamptz) language plpgsql security definer set search_path = '' as $$ begin perform private.require_urban_pipeline_authority(p_actor_user_id, p_organization_id, p_module, p_purpose_code); return query select structure.id, development.id, development.internal_reference, structure.internal_reference, structure.structure_kind, structure.created_at from public.urban_development_structures structure join public.urban_developments development on development.id = structure.development_id and development.organization_id = structure.organization_id where structure.organization_id = p_organization_id and structure.state = 'draft' and development.state = 'draft' order by structure.created_at desc, structure.id asc; end; $$;
revoke all on function public.urban_create_draft_development_structure(uuid, uuid, public.operating_module, text, uuid, text, public.urban_development_structure_kind, uuid) from public, anon, authenticated; revoke all on function public.urban_list_draft_development_structures(uuid, uuid, public.operating_module, text) from public, anon, authenticated; grant execute on function public.urban_create_draft_development_structure(uuid, uuid, public.operating_module, text, uuid, text, public.urban_development_structure_kind, uuid) to service_role; grant execute on function public.urban_list_draft_development_structures(uuid, uuid, public.operating_module, text) to service_role;
comment on table public.urban_development_structures is 'A109: torre ou bloco interno em rascunho; sem unidades, pavimentos, metragem, endereço, estoque, disponibilidade, preço, proposta, contrato ou financeiro.';
